CREATE TABLE "view_as_audit" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "view_as_audit_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"admin_sub" text NOT NULL,
	"admin_email" text,
	"client_id" bigint,
	"client_slug" text NOT NULL,
	"as_user_id" text,
	"action" text NOT NULL,
	"path" text,
	"method" text,
	"duration_minutes" integer,
	"user_agent" text,
	CONSTRAINT "view_as_audit_action_check" CHECK ("view_as_audit"."action" IN ('start', 'exit', 'expire', 'blocked_write')),
	CONSTRAINT "view_as_audit_duration_check" CHECK ("view_as_audit"."duration_minutes" IS NULL OR "view_as_audit"."duration_minutes" IN (30, 60, 120)),
	CONSTRAINT "view_as_audit_ids_check" CHECK (length(btrim("view_as_audit"."admin_sub")) > 0 AND length(btrim("view_as_audit"."client_slug")) > 0)
);
